"""
What Lanvex may do in Lanvex Core through the API: exactly the least-privilege set documented for an
external NetBox (Lanvex docs/operations.md, "NetBox token permissions"), nothing more.
"""
import re
from dataclasses import dataclass

__all__ = (
    'CUSTOM_FIELDS',
    'ROLE_GROUPS',
    'SERVICE_PERMISSIONS',
    'TOKEN_PATTERN',
    'CustomFieldSpec',
    'ServicePermission',
)

# nbt_<12-character key>.<40-character secret>, generated by the Lanvex installer.
TOKEN_PATTERN = re.compile(r'^nbt_(?P<key>[A-Za-z0-9]{12})\.(?P<secret>[A-Za-z0-9]{40})$')

# Lanvex roles, as sent in the group header. Administrators become superusers in Lanvex Core.
ROLE_GROUPS = ('lanvex-admin', 'lanvex-readonly')


@dataclass(frozen=True)
class ServicePermission:
    name: str
    actions: tuple
    object_types: tuple
    description: str


SERVICE_PERMISSIONS = (
    ServicePermission(
        name='Lanvex: networks, addresses and VLANs',
        actions=('view', 'add', 'change', 'delete'),
        object_types=('ipam.prefix', 'ipam.ipaddress', 'ipam.vlan', 'ipam.iprange'),
        description=(
            'Lanvex creates, edits and deletes these on behalf of its users. IP ranges tagged lanvex-dhcp are '
            'the DHCP pools Lanvex serves.'
        ),
    ),
    ServicePermission(
        name='Lanvex: interfaces',
        actions=('view', 'add', 'change', 'delete'),
        object_types=('dcim.interface', 'virtualization.vminterface'),
        description=(
            'Lanvex edits 802.1Q mode and VLANs, records interfaces servers have, and adds or removes the VLAN '
            'interface of a network an administrator adds to or removes from a server.'
        ),
    ),
    ServicePermission(
        name='Lanvex: cables',
        actions=('view', 'add'),
        object_types=('dcim.cable',),
        description='Lanvex draws the topology from cables, and records a cable an administrator confirms from LLDP.',
    ),
    ServicePermission(
        name='Lanvex: tags',
        actions=('view', 'add'),
        object_types=('extras.tag',),
        description='Lanvex creates its tags (lanvex-gateway, lanvex-dhcp) once.',
    ),
    ServicePermission(
        name='Lanvex: reference data',
        actions=('view',),
        object_types=(
            'ipam.vrf', 'ipam.role', 'ipam.vlangroup',
            'dcim.device', 'dcim.site', 'dcim.devicerole', 'dcim.manufacturer',
            'tenancy.tenant', 'core.objectchange', 'virtualization.virtualmachine',
        ),
        description='Read only.',
    ),
)


@dataclass(frozen=True)
class CustomFieldSpec:
    name: str
    label: str
    object_type: str
    validation_regex: str
    description: str


# Fields Lanvex reads to serve DHCP. lanvex_init creates them; administrators fill them in Lanvex or here.
CUSTOM_FIELDS = (
    CustomFieldSpec(
        name='mac_address',
        label='MAC address',
        object_type='ipam.ipaddress',
        validation_regex=r'^([0-9a-f]{2}:){5}[0-9a-f]{2}$',
        description=(
            'Lanvex hands out this address by DHCP to the device with this MAC address (lowercase, with colons).'
        ),
    ),
    CustomFieldSpec(
        name='dhcp_lease_time',
        label='DHCP lease time',
        object_type='ipam.iprange',
        validation_regex=r'^([1-9][0-9]{0,4}[mhd]|infinite)$',
        description='How long a device keeps an address from this DHCP pool: 30m, 12h, 2d or infinite. Empty: 12h.',
    ),
)
